/** Bytes of one instruction body a tool result may carry. */
export const MAX_FOLDER_INSTRUCTIONS_LENGTH = 32 * 1024
/** Bytes all the bodies one tool result carries may add up to, so nested folders
 * cannot stack several full-size bodies onto a single result. */
export const MAX_FOLDER_INSTRUCTIONS_TOTAL = 48 * 1024

export type FolderInstruction = {
	/** The instruction resource. */
	path: string
	/** The directory it covers, with a trailing `/`: `f/billing/AGENTS` covers `f/billing/`. */
	scope: string
}

export function folderInstructionScope(path: string): string {
	return path.slice(0, path.lastIndexOf('/') + 1)
}

/** The instructions covering any of `paths`, outermost scope first, so a nested
 * folder's instructions come last and read as the more specific ones. A path naming
 * the folder itself (`f/billing`, as a pipeline's is) is covered too. */
export function instructionsCovering(
	instructions: readonly FolderInstruction[],
	paths: readonly string[]
): FolderInstruction[] {
	return instructions
		.filter((i) => paths.some((p) => `${p}/`.startsWith(i.scope)))
		.sort((a, b) => a.scope.length - b.scope.length || a.path.localeCompare(b.path))
}

/** Cut `text` to `maxBytes` of UTF-8, marking the cut so a reader (the model
 * included) can tell truncation from a body that simply ends there.
 *
 * For the body, whose cap is a byte budget: 64k CJK characters are ~192 KiB, so a
 * code-unit cut would let three times the intended payload through. */
export function truncateForPrompt(text: string, maxBytes: number): string {
	const encoded = new TextEncoder().encode(text)
	if (encoded.byteLength <= maxBytes) return text
	// `fatal: false` replaces the partial code point a byte-aligned cut can leave
	// with U+FFFD; dropping it keeps the tail clean.
	const cut = new TextDecoder('utf-8').decode(encoded.slice(0, maxBytes)).replace(/�$/, '')
	return `${cut}… [truncated]`
}

export function folderInstructionsOpeningTag(path: string): string {
	return `<folder_instructions path="${path}"`
}

export function formatFolderInstructions(
	blocks: readonly { instruction: FolderInstruction; body: string }[]
): string {
	// The budget goes innermost first: the most specific instructions are the last to
	// be cut. An outer body the budget no longer reaches keeps its tag, so it still
	// counts as delivered, with the cut marked.
	let remaining = MAX_FOLDER_INSTRUCTIONS_TOTAL
	const bodies = [...blocks].reverse().map(({ body }) => {
		const cut = truncateForPrompt(body, Math.min(MAX_FOLDER_INSTRUCTIONS_LENGTH, remaining))
		remaining = Math.max(0, remaining - new TextEncoder().encode(cut).byteLength)
		return cut
	})
	bodies.reverse()
	return blocks
		.map(
			({ instruction }, i) =>
				`${folderInstructionsOpeningTag(instruction.path)} scope="${instruction.scope}">\n${bodies[i]}\n</folder_instructions>`
		)
		.join('\n\n')
}

// What the review asks of the model and how its answer is read, for every place it runs: the
// deployment request panel and the drafts review here, and `wmill review` on a git sync pull request, which carries
// this module through cli/generate-ai-review.ts. Keep it free of `$lib` imports; the
// staleness test in cli/test/ai_review_bundle_unit.test.ts fails when the CLI's copy drifts.


/**
 * Review instructions are resources of this type: a markdown file resource whose
 * `value.content` applies to every changed item under the directory it lives in.
 */
export const REVIEW_INSTRUCTIONS_RESOURCE_TYPE = 'ai_review_instruction'

export type AiReviewSeverity = 'high' | 'medium' | 'low'

export type AiReviewFinding = {
	id: string
	/** Empty when the finding names no changed item. */
	kind: string
	path: string
	severity: AiReviewSeverity
	comment: string
	/** Pull request reviews only: the changed file and line the finding is anchored to. */
	file?: string
	line?: number
	side?: 'LEFT' | 'RIGHT'
}

// A variable's value is read decrypted and a resource's value holds credentials, so neither may
// reach the model: they are reviewed by name and change type only.
export const VALUE_WITHHELD_KINDS = new Set(['variable', 'resource'])

export const PER_SIDE_CHAR_CAP = 20_000
export const TOTAL_CHAR_BUDGET = 160_000
// Under the Anthropic SDK's non-streaming pre-flight max_tokens limit.
export const MAX_OUTPUT_TOKENS = 8_000

/**
 * What is being reviewed: a fork's deployment request, a workspace's undeployed drafts, or a
 * pull request on a git sync repo.
 */
export type ReviewSubject = 'deployment_request' | 'draft' | 'pull_request'

const INTRO: Record<ReviewSubject, string> = {
	deployment_request:
		'You review a Windmill deployment request: a set of changes made in a fork workspace that will be merged into its parent workspace. Each changed item is given with its parent version (what is deployed now) and its fork version (what will be deployed).',
	draft:
		'You review drafts in a Windmill workspace: changes saved to items of the workspace but not deployed yet. Each changed item is given with its deployed version (what is deployed now) and its draft version (what will be deployed).',
	pull_request:
		"You review a pull request on a git repository that Windmill's git sync keeps in step with a workspace: merging it deploys its changes. Each changed item is given with the files that make it up in the repository, each as a unified diff of the base branch (what is deployed now) against the pull request (what will be deployed). Every diff line starts with its line number: R<n> for line n of the pull request's version of the file, L<n> for line n of the base version, then + for an added line, - for a removed one and a space for unchanged context."
}

const ITEM_ANSWER_SHAPE =
	'{"summary": "<one or two sentences on what the change does and its overall risk>", "findings": [{"kind": "<item kind as given>", "path": "<item path as given>", "severity": "high" | "medium" | "low", "comment": "<the issue and what to do about it, under 80 words>"}]}'

const ANSWER_SHAPE: Record<ReviewSubject, string> = {
	deployment_request: ITEM_ANSWER_SHAPE,
	draft: ITEM_ANSWER_SHAPE,
	pull_request:
		'{"summary": "<one or two sentences on what the change does and its overall risk>", "findings": [{"kind": "<item kind as given>", "path": "<item path as given>", "file": "<the file the issue is in, as given>", "line": "<the R or L line number the issue is on, as given, such as R12, or null for the file as a whole>", "severity": "high" | "medium" | "low", "comment": "<the issue and what to do about it, under 80 words>"}]}'
}

const SOURCE: Record<ReviewSubject, string> = {
	deployment_request: 'The parent workspace',
	draft: 'The workspace',
	pull_request: "The repository's base branch"
}

const APPROVED: Record<ReviewSubject, string> = {
	deployment_request: 'the merge',
	draft: 'the deployment',
	pull_request: 'the merge'
}

export function reviewSystemPrompt(subject: ReviewSubject): string {
	return `${INTRO[subject]} An item can be a script, flow, app, schedule, trigger, folder, resource type, datatable migration, variable or resource.

Report only issues a reviewer should act on before approving ${APPROVED[subject]}:
- bugs and logic errors introduced by the change
- breaking changes: removed or renamed inputs, changed input types, changed outputs that callers may rely on
- risky operational changes: schedules retimed, triggers pointed at a different script or flow, folder owners or permissions, app policies, destructive migrations
- hardcoded secrets or credentials
- deletions that look unintended

Do not comment on style, naming, formatting or lockfiles, and do not praise. Do not repeat a finding for every item it touches. An item with no issue gets no finding.

Answer with JSON only, no prose around it, in this shape:
${ANSWER_SHAPE[subject]}`
}

/** The system prompt addition carrying the review instructions that apply, or '' for none. */
export function reviewInstructionsSection(
	subject: ReviewSubject,
	blocks: readonly { instruction: FolderInstruction; body: string }[]
): string {
	if (blocks.length === 0) return ''
	// Hardcoded secrets and unintended deletions stay a floor: a folder's writers steer the
	// review of their own changes, so they must not be able to switch those checks off.
	return `\n\n${SOURCE[subject]} gives the review instructions below, each for the changed items under the folder in its scope. For those items they take precedence over the instructions above, and a nested folder's over its parent folder's. They may ask you to check more, check less or weigh severity differently, except that hardcoded secrets or credentials and deletions that look unintended are always reported. The answer is still the JSON above.\n\n${formatFolderInstructions(blocks)}`
}

/** One side of a changed item as the model reads it, lockfiles dropped and capped. */
export function renderItemValue(value: unknown): string {
	if (value == null) return '(none)'
	// Flows and apps nest their inline scripts' lockfiles, so they are dropped at any depth.
	const text =
		typeof value === 'string'
			? value
			: JSON.stringify(value, (key, v) => (key === 'lock' ? undefined : v), 2)
	return capText(text, PER_SIDE_CHAR_CAP)
}

export function capText(text: string, cap: number): string {
	return text.length > cap
		? `${text.slice(0, cap)}\n… (truncated, ${text.length - cap} more characters)`
		: text
}

/**
 * Packs item sections into the prompt in order. The first section that does not fit spends
 * the budget, and every item after it is listed by name only: `used` alone could stay under
 * the cap forever, and a caller that reads items lazily stops reading once `spent` is set.
 */
export class ReviewBudget {
	included: string[] = []
	/** `kind:path` of the changed items reviewed by name only. */
	omitted: string[] = []
	spent = false
	private used = 0

	add(key: string, section: string): void {
		if (!this.spent && this.used + section.length <= TOTAL_CHAR_BUDGET) {
			this.included.push(section)
			this.used += section.length
		} else {
			this.spent = true
			this.omitted.push(key)
		}
	}

	userPrompt(header: string): string {
		let user = `${header}\n\n${this.included.join('\n\n')}`
		if (this.omitted.length > 0) {
			user += `\n\nAlso changed, contents not shown for size:\n${this.omitted.map((o) => `- ${o}`).join('\n')}`
		}
		return user
	}
}

/** What a finding may be anchored to. */
export type ReviewAnchors = {
	/** `kind:path` of every changed item. */
	items: ReadonlySet<string>
	/** Pull request reviews: for each changed file, the line numbers a comment can be placed on. */
	lines?: ReadonlyMap<string, { LEFT: ReadonlySet<number>; RIGHT: ReadonlySet<number> }>
}

export function parseReviewAnswer(
	text: string,
	anchors: ReviewAnchors
): { summary: string; findings: AiReviewFinding[] } {
	const start = text.indexOf('{')
	const end = text.lastIndexOf('}')
	if (start === -1 || end <= start) {
		throw new Error('The AI answer was not in the expected format')
	}
	const parsed = JSON.parse(text.slice(start, end + 1)) as {
		summary?: unknown
		findings?: unknown
	}
	// Anchoring a comment needs an item, file and line the change actually has, so a finding
	// naming anything else keeps its comment but loses the anchor rather than being posted
	// against a phantom.
	const findings: AiReviewFinding[] = []
	for (const [i, raw] of (Array.isArray(parsed.findings) ? parsed.findings : []).entries()) {
		if (!raw || typeof raw.comment !== 'string' || !raw.comment.trim()) continue
		const anchored = anchors.items.has(`${raw.kind}:${raw.path}`)
		const finding: AiReviewFinding = {
			id: String(i),
			kind: anchored ? raw.kind : '',
			path: anchored ? raw.path : '',
			severity: ['high', 'medium', 'low'].includes(raw.severity) ? raw.severity : 'medium',
			comment: raw.comment.trim()
		}
		const fileLines = typeof raw.file === 'string' ? anchors.lines?.get(raw.file) : undefined
		if (fileLines) {
			finding.file = raw.file
			const line = /^([LR])(\d+)$/.exec(String(raw.line ?? '').trim())
			const side = line?.[1] === 'L' ? 'LEFT' : 'RIGHT'
			if (line && fileLines[side].has(Number(line[2]))) {
				finding.side = side
				finding.line = Number(line[2])
			}
		}
		findings.push(finding)
	}
	const rank: Record<AiReviewSeverity, number> = { high: 0, medium: 1, low: 2 }
	findings.sort((a, b) => rank[a.severity] - rank[b.severity])
	return { summary: typeof parsed.summary === 'string' ? parsed.summary : '', findings }
}
